```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::response_channel;

struct Node;

impl Guest for Node {
    fn run(reply: AgentResponse) -> DeliveryConfirmation {
        // The contract's `requires len(text) <= 100000` holds of every input,
        // so the text is forwarded to the channel unchanged.
        let confirmation = response_channel::send(&reply.text);

        // The session identity and the delivery flag belong to the host
        // channel. The node never fabricates either: if the channel did not
        // accept the message, or did not stamp a session, the postconditions
        // cannot honestly be met, so the node traps rather than emit a
        // confirmation that claims a delivery that did not happen.
        if !confirmation.delivered {
            panic!("response channel did not accept the reply");
        }
        if confirmation.session.is_empty() {
            panic!("response channel returned no session identity");
        }

        DeliveryConfirmation {
            session: confirmation.session,
            delivered: confirmation.delivered,
        }
    }
}

export!(Node);
```

